from pathlib import Path
import shutil,json,hashlib
R=Path(__file__).resolve().parents[1]; O=R/'output/posters/concise'; O.mkdir(exist_ok=True);(O/'screens').mkdir(exist_ok=True)
source=R/'output/posters/ink/screens'
manifest={}
for f in source.glob('*.png'):
 shutil.copy2(f,O/'screens'/f.name);manifest[f.name]=hashlib.sha256(f.read_bytes()).hexdigest()
(O/'screenshot-sha256.json').write_text(json.dumps(manifest,indent=2))
css='''*{box-sizing:border-box}body{margin:0;background:#dfe8ec;color:#133841;font-family:"PingFang SC","Hiragino Sans GB",sans-serif}h1,h2,h3,p,figure{margin:0}.poster{--accent:#b9682a;--tint:#f1e6d8;width:1920px;height:1080px;position:relative;overflow:hidden;background:#f3f7f8;padding:48px 66px}.top{display:flex;justify-content:space-between;align-items:center;height:54px}.brand{display:flex;align-items:center;gap:14px}.brandmark{width:43px;height:48px;border-radius:12px 12px 22px 22px;background:#153f46;display:grid;place-items:center;color:#fff;font:29px "Songti SC",serif}.brand strong{font-size:28px;letter-spacing:1.3px}.brand small{display:block;margin-top:4px;font-size:15px;color:#617a82}.stamp{text-align:right;font-size:15px;line-height:1.8;color:#617a82}.hero{display:flex;align-items:center;justify-content:space-between;margin-top:42px}.eyebrow{color:var(--accent);font-size:19px;font-weight:600;letter-spacing:1px;margin-bottom:12px}.hero h1{font-size:65px;line-height:1.2;letter-spacing:-2px;font-weight:650}.place{text-align:right;color:var(--accent);font-size:26px;font-weight:600;padding-top:38px}.groups{display:grid;grid-template-columns:420px 1fr;gap:36px;margin-top:43px}.grouphead{height:44px;border-bottom:2px solid #c6d9db;margin-bottom:20px;display:flex;align-items:center;justify-content:space-between}.grouphead strong{font-size:22px;font-weight:600}.grouphead span{font-size:15px;color:#638088}.grouphead.danger{border-color:var(--accent)}.grouphead.danger strong{color:var(--accent)}.row{display:grid;grid-template-columns:repeat(3,420px);gap:36px}.screen{display:block;width:420px;height:308px;object-fit:contain;background:#000;border-radius:12px;box-shadow:0 14px 30px #193a4412}.caption{display:flex;align-items:center;justify-content:space-between;margin-top:19px}.caption b{font-size:22px;font-weight:600}.caption span{font-size:17px;color:#657d85}.caption .focus{color:var(--accent)}.benefits{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;margin-top:47px;padding:26px 30px;background:var(--tint);border-radius:10px}.benefit{display:flex;align-items:center;gap:15px}.benefit i{font-size:28px;font-style:normal;color:var(--accent);width:30px}.benefit strong{font-size:25px;font-weight:600}.benefit small{display:block;font-size:16px;color:#61727a;margin-top:5px}.note{margin-top:20px;font-size:16px;color:#5f757d;line-height:1.6}.note.volcano{color:#a04c31;font-weight:500}.footer{position:absolute;bottom:35px;left:66px;right:66px;border-top:1px solid #cbdade;padding-top:18px;display:flex;justify-content:space-between;align-items:end;font-size:14px;line-height:1.8;color:#6a7f86}.folio{font:13px monospace;letter-spacing:1.4px;text-align:right}.overview{--accent:#087d69;--tint:#e0eeea}.overview .hero{margin-top:34px}.overview .hero h1{font-size:66px}.overview-layout{display:grid;grid-template-columns:440px 1fr;gap:46px;margin-top:45px}.pitch{padding-top:4px}.pitch .claim{font-size:31px;line-height:1.5;font-weight:600;letter-spacing:-.5px;margin-bottom:25px}.features{display:flex;flex-direction:column;gap:23px}.feature{border-left:3px solid #9abfb6;padding-left:17px}.feature b{font-size:25px;font-weight:600}.feature p{font-size:18px;color:#647c84;margin-top:5px}.overview-screens{display:grid;grid-template-columns:636px 636px;gap:30px}.overview-screens .screen{width:636px;height:466.4px}.overview-screens .caption b{font-size:23px}.coverage{margin-top:39px;border-top:1px solid #cbdade;padding-top:23px;display:flex;align-items:center;gap:25px;font-size:19px;color:#3c626b}.coverage strong{color:#107a67;font-size:25px;white-space:nowrap}.coverage span{display:inline-block;margin-right:19px}.overview .note{margin-top:17px}.overview .footer{bottom:28px}.gallery{max-width:1300px;margin:40px auto;padding:0 24px}.gallery h1{font-size:34px}.gallery p{line-height:1.8;margin:12px 0;color:#587680}.gallery section{margin:35px 0}.gallery img{width:100%;height:auto;margin-top:12px}.gallery a{color:#146a5d}.gallery h2{font-size:24px}@page{size:1920px 1080px;margin:0}@media print{body{background:white}.poster{break-after:page}}
'''
scenes=[dict(id='ikeda',type='地震',title='震时，先护身。',place='大阪府池田市',accent='#b76725',tint='#f3e8d9',state='地震信息出现',action='降低重心 · 保护头部',benefits=[('!','天气卡变预警卡','关注点随情境切换'),('◎','所在地匹配','震度、震级分开展示'),('＋','行动要点同屏','先保护自己，再查看信息')],note='全部数据为模拟；首页灾害态为跳转前暂停截图。地震信息为震后信息。'),dict(id='wakayama',type='火山 · 虚构演练',title='看清警戒，遵循管制。',place='和歌山县 · 虚构情境',accent='#b05238',tint='#f3e5df',state='火山警戒出现',action='保护头部 · 遵循管制',benefits=[('!','警戒信息前置','首页直接显示火山警报'),('△','等级与管制分列','明确当前应对依据'),('＋','关键行动同屏','关注警报与现场指示')],note='和歌山及周边无活火山；本图为虚构演练，不代表当地风险。首页灾害态为跳转前暂停截图。'),dict(id='iwate',type='地震 + 海啸',title='不等海浪，立即避难。',place='岩手县沿岸 · 宫古市',accent='#246b91',tint='#e1edf4',state='海啸与地震并列',action='先防护摇晃 · 随后向高处',benefits=[('≋','海啸信息优先','多灾种时优先查看海啸'),('◎','确认适用沿岸','市町村与沿岸分别核对'),('＋','不等警报或倒计时','强烈或持续摇晃后立即避难')],note='全部数据为模拟；首页灾害态为跳转前暂停截图。海啸详情优先，指南需点击进入。')]
def header():return '<header class="top"><div class="brand"><span class="brandmark">守</span><div><strong>まもり MAMORI</strong><small>Rokid Glasses 日本防灾智能体</small></div></div><div class="stamp">真实 Ink 页面截图<br>开发原型 · 情境模拟</div></header>'
def footer(label):return f'<footer class="footer"><p>模拟数据，非实时警报或眼镜实拍。紧急时遵循官方与现场指示。<br>真机与后台送达待验证；秒级地震预警、自动导航未接通。</p><div class="folio">MAMORI / v0.2.2<br>{label}</div></footer>'
def save(id,title,body):
 (O/f'{id}.html').write_text(f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>{title}</title><style>{css}</style></head><body>{body}</body></html>')
for s in scenes:
 benefits=''.join(f'<div class="benefit"><i>{icon}</i><div><strong>{title}</strong><small>{sub}</small></div></div>' for icon,title,sub in s['benefits'])
 body=f'''<main class="poster" style="--accent:{s['accent']};--tint:{s['tint']}">{header()}<div class="hero"><div><p class="eyebrow">{s['type']}</p><h1>{s['title']}</h1></div><p class="place">{s['place']}</p></div>
 <div class="groups"><section><div class="grouphead"><strong>日常</strong><span>看天气 · 做准备</span></div><img class="screen" src="screens/{s['id']}-daily.png" alt="日常首页：原生 Ink 模拟截图"><div class="caption"><b>日常首页</b><span>天气与准备</span></div></section><section><div class="grouphead danger"><strong>灾害情境</strong><span>首页提示 → 灾害详情 → 行动指南</span></div><div class="row"><figure><img class="screen" src="screens/{s['id']}-warning.png" alt="灾害首页中间状态：原生 Ink 模拟截图"><figcaption class="caption"><b class="focus">首页切换</b><span>{s['state']}</span></figcaption></figure><figure><img class="screen" src="screens/{s['id']}-alert.png" alt="灾害详情：原生 Ink 模拟截图"><figcaption class="caption"><b>灾害详情</b><span>关键信息集中看</span></figcaption></figure><figure><img class="screen" src="screens/{s['id']}-guide.png" alt="行动指南：原生 Ink 截图"><figcaption class="caption"><b>行动指南</b><span>首要行动 + 三条要点</span></figcaption></figure></div></section></div>
 <div class="benefits">{benefits}</div><p class="note {'volcano' if s['id']=='wakayama' else ''}">{s['note']}</p>{footer(s['type'])}</main>'''
 save(s['id'],'MAMORI · '+s['place'],body)
body=f'''<main class="poster overview">{header()}<div class="hero"><div><p class="eyebrow">产品总览</p><h1>日常看天气，灾时看行动。</h1></div><p class="place">所在地信息 → 防灾行动</p></div>
<div class="overview-layout"><div class="pitch"><p class="claim">把关键信息与下一步，<br>放进一屏。</p><div class="features"><div class="feature"><b>确认所在地</b><p>GPS、地址、地区、邮编入口</p></div><div class="feature"><b>天气与灾害信息</b><p>首页随匹配通报切换重点</p></div><div class="feature"><b>双语离线指南</b><p>首要行动与三条要点同屏</p></div><div class="feature"><b>按灾种查询避难地点</b><p>结合所在地，查看适用地点</p></div></div></div><div class="overview-screens"><figure><img class="screen" src="screens/ikeda-daily.png" alt="MAMORI 日常首页原生 Ink 截图"><figcaption class="caption"><b>平时：看天气，做好准备</b></figcaption></figure><figure><img class="screen" src="screens/iwate-guide.png" alt="MAMORI 海啸行动指南原生 Ink 截图"><figcaption class="caption"><b>灾时：明确行动，查看指南</b></figcaption></figure></div></div>
<div class="coverage"><strong>7 类指南</strong><div><span>地震</span><span>海啸</span><span>滑坡泥石流</span><span>暴雨洪水</span><span>台风</span><span>火山</span><span>日常准备</span></div></div><p class="note">中日双语 · 原生 Ink 界面 · 灾害信息需接通后端；避难地点开放与路线安全需另行确认。</p>{footer('PRODUCT OVERVIEW')}</main>'''
save('overview','MAMORI · 产品总览',body)
items=[('overview','产品总览'),('ikeda','池田市 · 地震'),('wakayama','和歌山 · 虚构火山演练'),('iwate','岩手沿岸 · 地震与海啸')]
sections=''.join(f'<section><h2>{name}</h2><a href="{id}.png"><img src="{id}.png" alt="{name}海报"></a><p><a href="{id}.png">下载高清 PNG</a>　<a href="{id}.html">查看版式</a></p></section>' for id,name in items)
(O/'index.html').write_text(f'<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MAMORI 精简宣传海报</title><style>{css}</style><body><main class="gallery"><h1>MAMORI · 精简宣传海报</h1><p>三种灾害情境 + 产品总览。全部使用真实 Ink 渲染截图。</p>{sections}</main></body></html>')
(O/'posters.json').write_text(json.dumps(items,ensure_ascii=False))
print('Built four concise poster layouts from existing native Ink screenshots.')
